    if text is None or not isinstance(text, str):
        return None

    text = text.strip()
    if not text:
        return None

    # Check if it ends with '%'
    if text.endswith('%'):
        # Remove the '%' and strip spaces
        num_part = text[:-1].strip()
        if not num_part:
            return None
        try:
            return float(num_part) / 100
        except ValueError:
            return None
    else:
        # No '%' sign, just a number
        try:
            return float(text) / 100
        except ValueError:
            return None
